from pages5 import mk
from pages9 import F,AFR,ANL,SFR,SNL
U='https://unbanz.com/'
IGL=lambda l:[('Account Status','https://help.instagram.com/338481628002750',{'fr':'Dans l’application : Paramètres, puis Statut du compte.','nl':'In de app: Instellingen, dan Accountstatus.'}[l]),('Help Center','https://help.instagram.com/366993040048856',{'fr':'Page d’aide officielle sur les comptes désactivés.','nl':'Officiële hulppagina over uitgeschakelde accounts.'}[l])]
FBL=lambda l:[('Account Status','https://www.facebook.com/help/',{'fr':'Aide officielle de Facebook, dont le Statut du compte.','nl':'Officiële hulp van Facebook, ook Accountstatus.'}[l])]
def N(en,fr,nl,plat,text_fr,text_nl,t_fr,t_nl,m_fr,m_nl,a_fr,a_nl,st_fr,st_nl,fq_fr,fq_nl):
    H=[('en',U+en+'/'),('fr',U+'fr/'+fr+'/'),('nl',U+'nl/'+nl+'/'),('x-default',U+en+'/')]
    lk=IGL if plat=='Instagram' else FBL
    def one(l,slug,text,t,m,a,st,fq,A,S):
        sec=('<h2 id="signification">Ce que cela veut dire</h2>' if l=='fr' else '<h2 id="betekenis">Wat het betekent</h2>')+f'<p>{m}</p>'+('<h2 id="premiere-heure">La première heure</h2>' if l=='fr' else '<h2 id="eerste-uur">Het eerste uur</h2>')+'<ol>'+''.join(f'<li>{s}</li>' for s in st)+'</ol>'
        desc=(f'Ce que signifie le message {plat} « {text} », que faire dans la première heure et quel lien officiel utiliser. Mis à jour en novembre 2026.' if l=='fr' else f'Wat de {plat}-melding “{text}” betekent, wat u in het eerste uur doet en welke officiële link u gebruikt. Bijgewerkt november 2026.')
        h1=(f'« {text} » sur {plat} : ce que cela veut dire' if l=='fr' else f'“{text}” op {plat}: wat het betekent')
        lede=('Vous avez vu ce message exact. Voici ce qu’il veut dire en général, et quoi faire ensuite.' if l=='fr' else 'U zag precies deze melding. Dit betekent ze meestal, en dit doet u daarna.')
        cards=[('Capture','Gardez le message et la date.'),('Un seul appel','Des mots simples, une fois.'),('Pas de nouveau compte','Attendez la décision.')] if l=='fr' else [('Schermafbeelding','Bewaar melding en datum.'),('Eén bezwaar','Gewone woorden, één keer.'),('Geen nieuw account','Wacht op de beslissing.')]
        rel=f'<a href="/{en}/">'+('version anglaise' if l=='fr' else 'Engelse versie')+'</a>, '+(f'<a href="/nl/{nl}/">version néerlandaise</a>' if l=='fr' else f'<a href="/fr/{fr}/">Franse versie</a>')+'.'
        return F(mk(f'{l}/{slug}',t,(f'Message « {text} »' if l=='fr' else f'Melding “{text}”'),desc,h1,lede,a,cards,sec,[(l,('Liens officiels' if l=='fr' else 'Officiële links'),lk(l))],[A,S],rel,fq),lang=l,hreflang=H)
    return [one('fr',fr,text_fr,t_fr,m_fr,a_fr,st_fr,fq_fr,AFR,SFR),one('nl',nl,text_nl,t_nl,m_nl,a_nl,st_nl,fq_nl,ANL,SNL)]
